module binary_tree_generator (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] N,  // 1 to 15\n    output reg [15:0] preorder_data,\n    output reg [14:0] preorder_index,\n    output reg done,\n    output reg valid\n);\n    // State declarations\n    localparam [2:0] IDLE            = 3'd0;\n    localparam [2:0] CALCULATE_NODES = 3'd1;\n    localparam [2:0] CONSTRUCT_LEAVES= 3'd2;\n    localparam [2:0] CONSTRUCT_LEVEL = 3'd3;\n    localparam [2:0] PREORDER_INIT   = 3'd4;\n    localparam [2:0] PREORDER_OUTPUT = 3'd5;\n    localparam [2:0] FINISHED        = 3'd6;\n    \n    // Internal storage\n    reg [15:0] tree [0:32767];\n    reg [15:0] stack [0:32767];\n    reg [14:0] sp;\n    reg [14:0] tp;\n    reg [14:0] total_nodes;\n    reg [3:0] current_level;\n    reg [14:0] level_start_index;\n    reg [14:0] level_node_count;\n    reg [2:0] state, next_state;\n    reg [15:0] sum_left;\n    reg [15:0] sum_right;\n    integer i;\n\n    // State transition\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            valid <= 1'b0;\n            sp <= 15'd0;\n            tp <= 15'd0;\n            current_level <= 4'd0;\n            preorder_index <= 15'd0;\n            sum_left <= 16'd0;\n            sum_right <= 16'd0;\n            for (i = 0; i < 32768; i = i + 1) begin\n                tree[i] <= 16'd0;\n                stack[i] <= 16'd0;\n            end\n        end else begin\n            state <= next_state;\n        end\n    end\n\n    // Next state logic\n    always @(*) begin\n        next_state = state;\n        case (state)\n            IDLE: if (start) next_state = CALCULATE_NODES;\n            CALCULATE_NODES: next_state = (N == 4'd1) ? PREORDER_INIT : CONSTRUCT_LEAVES;\n            CONSTRUCT_LEAVES: begin\n                if (current_level >= (N - 4'd2)) next_state = CONSTRUCT_LEVEL;\n                else next_state = CONSTRUCT_LEAVES;\n            end\n            CONSTRUCT_LEVEL: begin\n                if (current_level == 4'd1) next_state = PREORDER_INIT;\n                else next_state = CONSTRUCT_LEVEL;\n            end\n            PREORDER_INIT: next_state = PREORDER_OUTPUT;\n            PREORDER_OUTPUT: next_state = (sp == 15'd0) ? FINISHED : PREORDER_OUTPUT;\n            FINISHED: next_state = FINISHED;\n            default: next_state = IDLE;\n        endcase\n    end\n\n    // Main logic\n    always @(posedge clk) begin\n        done <= 1'b0;\n        valid <= 1'b0;\n\n        case (state)\n            CALCULATE_NODES: begin\n                total_nodes <= (16'd1 << N) - 16'd1;\n                current_level <= N - 4'd1;\n                tp <= 15'd0;\n            end\n\n            CONSTRUCT_LEAVES: begin\n                if (current_level == (N - 4'd1)) begin\n                    level_node_count <= 15'd1 << (N - 4'd1);\n                    level_start_index <= (15'd1 << (N - 4'd1)) - 15'd1;\n                    \n                    // Assign leaves in pairs\n                    for (i = 0; i < (level_node_count >> 1); i = i + 1) begin\n                        tree[level_start_index + (i << 1)]     <= (i << 2) + 16'd1;\n                        tree[level_start_index + (i << 1) + 1] <= (i << 2) + 16'd1 + (16'd1 << (N - 4'd2));\n                    end\n                    current_level <= current_level - 4'd1;\n                end\n            end\n\n            CONSTRUCT_LEVEL: begin\n                level_node_count <= 15'd1 << current_level;\n                level_start_index <= (15'd1 << current_level) - 15'd1;\n\n                for (i = 0; i < level_node_count; i = i + 1) begin\n                    sum_left <= tree[(level_start_index + i) << 1];\n                    sum_right <= tree[((level_start_index + i) << 1) + 1];\n                    \n                    tree[level_start_index + i] <= (current_level == (N - 4'd2)) ? \n                        (16'd1 << (N - 4'd1)) + i : \n                        (16'd1 << (N - 4'd1)) + (16'd1 << (N - 4'd2)) + i;\n                end\n                current_level <= current_level - 4'd1;\n            end\n\n            PREORDER_INIT: begin\n                sp <= 15'd0;\n                if (total_nodes > 15'd0) begin\n                    stack[sp] <= 15'd1;\n                    sp <= sp + 15'd1;\n                end\n                preorder_index <= 15'd0;\n            end\n\n            PREORDER_OUTPUT: begin\n                if (sp > 15'd0) begin\n                    sp <= sp - 15'd1;\n                    preorder_data <= tree[stack[sp]];\n                    valid <= 1'b1;\n                    preorder_index <= preorder_index + 15'd1;\n\n                    if ((stack[sp] << 1) + 1 <= total_nodes) begin\n                        stack[sp] <= (stack[sp] << 1) + 1;\n                        sp <= sp + 15'd1;\n                    end\n                    if (stack[sp] << 1 <= total_nodes) begin\n                        stack[sp] <= stack[sp] << 1;\n                        sp <= sp + 15'd1;\n                    end\n                end\n            end\n\n            FINISHED: done <= 1'b1;\n        endcase\n    end\nendmodule